"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { Icon } from "@/components/ui/Icon";
import { navigation, isActive, isFullscreen } from "./navigation";

export function NavBar() {
  const pathname = usePathname();
  const [email, setEmail] = useState<string | null>(null);
  const [signingOut, setSigningOut] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    const client = createClient();
    if (!client) return;
    let mounted = true;
    client.auth.getUser().then(({ data }) => { if (mounted) setEmail(data.user?.email ?? null); });
    const { data: { subscription } } = client.auth.onAuthStateChange((_, session) => setEmail(session?.user?.email ?? null));
    return () => { mounted = false; subscription.unsubscribe(); };
  }, []);
  if (isFullscreen(pathname)) return null;
  async function signOut() {
    setSigningOut(true);
    const result = await createClient()?.auth.signOut();
    if (result?.error) { setError("Could not sign out. Please try again."); setSigningOut(false); return; }
    window.location.assign("/");
  }
  return <header className="app-header">
    <div className="header-inner">
      <Link href="/" className="brand" aria-label="Outdoor OS home"><span className="brand-symbol"><Icon name="mountain" size={25} /></span><span>Outdoor<span className="brand-os">OS</span></span></Link>
      <nav className="desktop-nav" aria-label="Main navigation">{navigation.map(link => <Link key={link.href} href={link.href} aria-current={isActive(pathname, link) ? "page" : undefined} className={isActive(pathname, link) ? "active" : ""}>{link.label}</Link>)}</nav>
      <div className="header-actions">
        <Link href="/record" className="btn-primary header-record"><Icon name="record" size={17} />Record activity</Link>
        {email ? <><Link href="/you" className="avatar-button" aria-label="Your profile and activity log">{email[0].toUpperCase()}</Link><button className="icon-button signout-button" aria-label="Sign out" onClick={signOut} disabled={signingOut}><Icon name="logout" size={18} /></button></> : <Link href="/login" className="account-link"><Icon name="user" size={18} /><span>Sign in</span></Link>}
      </div>
    </div>
    {error && <p role="alert" className="notice error">{error}</p>}
  </header>;
}

