"use client";
import { useState, type FormEvent } from "react";
import Link from "next/link";
import { useBrowserCollection } from "@/hooks/useBrowserCollection";
import { useGear } from "@/hooks/useGear";
import { Icon } from "@/components/ui/Icon";
import { calcStats, convertWeight, type GearItem } from "@/lib/gear";
import { isTrip, isGearItem, tripDate, recordingLink, type Trip, type TripRoute } from "@/lib/trip-model";

interface Props { userId?: string; routes: TripRoute[]; initialTrail?: string; initialTrip?: string; createNew?: boolean }
export function TripsWorkspace(props: Props) {
  return props.userId ? <ConnectedTrips {...props} userId={props.userId} /> : <GuestTrips {...props} />;
}
function ConnectedTrips(props: Props & { userId: string }) {
  const { gear, loading, error } = useGear(props.userId);
  return <TripPlanner {...props} gear={gear} gearLoading={loading} gearError={error ?? ""} />;
}
function GuestTrips(props: Props) {
  const { items, loading, error } = useBrowserCollection("outdoor-gear:guest", isGearItem);
  return <TripPlanner {...props} gear={items} gearLoading={loading} gearError={error} />;
}
function TripPlanner({ userId, routes, initialTrail, initialTrip, createNew, gear, gearLoading, gearError }: Props & { gear: GearItem[]; gearLoading: boolean; gearError: string }) {
  const { items: trips, loading, error, update } = useBrowserCollection(`outdoor-trips:${userId ?? "guest"}`, isTrip);
  const initialRoute = routes.find(r => r.key === initialTrail);
  const [selectedId, setSelectedId] = useState(initialTrip ?? "");
  const [creating, setCreating] = useState(Boolean(createNew || initialRoute));
  const [addingGear, setAddingGear] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [message, setMessage] = useState("");
  const trip = trips.find(t => t.id === selectedId) ?? trips[0];
  const saveTrip = (patch: Partial<Trip>) => trip && update(list => list.map(t => t.id === trip.id ? { ...t, ...patch } : t));
  const stats = calcStats(trip?.items ?? []);
  const packed = trip?.items.filter(i => i.packed).length ?? 0;
  function createTrip(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const data = new FormData(e.currentTarget);
    const route = routes.find(r => r.key === data.get("route")) ?? null;
    const id = crypto.randomUUID();
    const newTrip: Trip = { id, name: String(data.get("name")).trim(), route, date: String(data.get("date")), days: Number(data.get("days")), notes: "", items: [], createdAt: new Date().toISOString() };
    if (!newTrip.name) return;
    if (update(list => [newTrip, ...list])) { setSelectedId(id); setCreating(false); setAddingGear(false); setMessage("Trip created. Next, add the gear you’re bringing."); }
  }
  function addGear(item: GearItem) {
    if (!trip) return;
    const next = { ...item, id: crypto.randomUUID(), gearId: item.id, packed: false };
    if (saveTrip({ items: [...trip.items, next] })) setMessage(`${item.name} added to your pack.`);
  }
  function exportList() {
    if (!trip) return;
    const lines = [trip.name, `${tripDate(trip.date)} · ${trip.days} days`, trip.route?.name ?? "Custom route", "", ...trip.items.map(i => `${i.packed ? "[x]" : "[ ]"} ${i.name} × ${i.qty} — ${convertWeight(i.weight * i.qty, "lb")} lb`), "", `Base weight: ${convertWeight(stats.baseWeight, "lb")} lb`, `Total weight: ${convertWeight(stats.totalWeight, "lb")} lb`, "", trip.notes];
    const url = URL.createObjectURL(new Blob([lines.join("\n")], { type: "text/plain" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${trip.name.replace(/[^a-z0-9]/gi, "-")}-packing-list.txt`; anchor.click(); URL.revokeObjectURL(url);
    setMessage("Packing list downloaded.");
  }
  return <div className="workspace">
    <div className="page-heading"><div><h1>Good trips start here.</h1><p>Your route, your dates, and everything coming along.</p></div><button className="btn-primary" onClick={() => { setCreating(true); setConfirmDelete(false); }}><Icon name="plus" size={18} />New trip</button></div>
    <p className="local-storage-note"><Icon name="check" size={15} />Plans are saved in this browser. Download a checklist to take it with you.</p>
    {(error || gearError) && <p role="alert" className="notice error">{error || gearError}</p>}
    {message && <p className="notice" role="status">{message}</p>}
