      {trip.items.length === 0 ? <div className="packing-empty"><Icon name="pack" size={32} /><h3>Bring only what you need.</h3><p>Add items from your gear locker to build this trip’s pack.</p><button className="text-link" onClick={() => setAddingGear(true)}>Choose your gear<Icon name="arrow" size={16} /></button></div> : <div className="packing-items">{trip.items.map(item => <div className={`packing-item ${item.packed ? "is-packed" : ""}`} key={item.id}><label><input type="checkbox" checked={item.packed} onChange={() => saveTrip({ items: trip.items.map(i => i.id === item.id ? { ...i, packed: !i.packed } : i) })} /><span><strong>{item.name}</strong><small>{item.category} · {item.type}{item.qty > 1 ? ` · Qty ${item.qty}` : ""}</small></span></label><span className="item-weight">{convertWeight(item.weight * item.qty, "lb")} lb</span><button className="icon-button" aria-label={`Remove ${item.name} from pack`} onClick={() => saveTrip({ items: trip.items.filter(i => i.id !== item.id) })}><Icon name="close" size={17} /></button></div>)}</div>}
      </section><section className="trip-notes"><label htmlFor="trip-notes">Trip notes</label><textarea key={trip.id} id="trip-notes" defaultValue={trip.notes} onBlur={e => { if (trip.notes !== e.target.value && saveTrip({ notes: e.target.value })) setMessage("Notes saved."); }} placeholder="Meeting point, permit reminders, food plans…" rows={3} /><small>Saved when you leave this field.</small></section></div>
      <aside className="pack-summary panel"><Icon name="pack" size={30} /><h2>Your pack, at a glance.</h2><dl><div><dt>Base weight</dt><dd>{convertWeight(stats.baseWeight, "lb")} <span>lb</span></dd></div><div><dt>Worn</dt><dd>{convertWeight(stats.wornWeight, "lb")} <span>lb</span></dd></div><div><dt>Consumables</dt><dd>{convertWeight(stats.consumableWeight, "lb")} <span>lb</span></dd></div><div className="pack-total"><dt>Total weight</dt><dd>{convertWeight(stats.totalWeight, "lb")} <span>lb</span></dd></div></dl><p>{stats.totalItems} pieces of gear · {packed === trip.items.length && trip.items.length ? "All packed" : "Pack in progress"}</p><button className="btn-ghost" onClick={exportList}><Icon name="download" size={17} />Download checklist</button><Link href={recordingLink(trip)} className="btn-primary"><Icon name="record" size={17} />Record this hike</Link><p className="storage-caption">GPS recording requires an account.{trip.route?.source === "guide" ? " Guide routes do not include navigation geometry." : ""}</p>{trip.route?.trailId && <Link className="text-link" href={`/explore/trails/${trip.route.trailId}`}>View trail details<Icon name="arrow" size={16} /></Link>}
      <div className="trip-delete">{confirmDelete ? <><p>Delete “{trip.name}” and its checklist?</p><button className="danger-button" onClick={() => { if (update(list => list.filter(t => t.id !== trip.id))) { setConfirmDelete(false); setMessage("Trip deleted."); } }}>Delete trip</button><button className="inline-button" onClick={() => setConfirmDelete(false)}>Keep trip</button></> : <button className="muted-button" onClick={() => setConfirmDelete(true)}>Delete trip</button>}</div></aside></div>
    </>}
  </div>;
}

