"use client";
import { useCallback, useMemo, useState, useSyncExternalStore } from "react";
const EVENT = "outdoor-workspace-change";
function subscribe(callback: () => void) { window.addEventListener("storage", callback); window.addEventListener(EVENT, callback); return () => { window.removeEventListener("storage", callback); window.removeEventListener(EVENT, callback); }; }
export function useBrowserCollection<T>(key: string, validate: (value: unknown) => value is T) {
  const [writeError, setWriteError] = useState("");
  const snapshot = useSyncExternalStore(subscribe, useCallback(() => { try { return localStorage.getItem(key) ?? "[]"; } catch { return "unavailable"; } }, [key]), () => null);
  const result = useMemo(() => {
    if (snapshot === null) return { items: [] as T[], error: "" };
    try { const parsed: unknown = JSON.parse(snapshot); if (!Array.isArray(parsed) || !parsed.every(validate)) throw new Error(); return { items: parsed as T[], error: "" }; }
    catch { return { items: [] as T[], error: "Saved data could not be read. Try another browser or restore browser storage before making changes." }; }
  }, [snapshot, validate]);
  const update = useCallback((transform: (current: T[]) => T[]) => {
    try {
      const parsed: unknown = JSON.parse(localStorage.getItem(key) ?? "[]");
      if (!Array.isArray(parsed) || !parsed.every(validate)) throw new Error();
      localStorage.setItem(key, JSON.stringify(transform(parsed)));
      setWriteError(""); window.dispatchEvent(new Event(EVENT)); return true;
    } catch { setWriteError("Your changes couldn’t be saved. Check browser storage and try again."); return false; }
  }, [key, validate]);
  return { items: result.items, loading: snapshot === null, error: writeError || result.error, update };
}

