import { PACK_TRAILS, type GearItem } from "@/lib/gear";
import type { Trail } from "@/lib/types";
export interface TripRoute {
  key: string; name: string; location: string; distance: number; elevation: number;
  days: string; difficulty: string; trailId?: string; image?: string; source: "catalog" | "guide";
}
export interface TripItem extends GearItem { packed: boolean; gearId?: string }
export interface Trip {
  id: string; name: string; route: TripRoute | null; date: string; days: number;
  notes: string; items: TripItem[]; createdAt: string;
}
export function getTripRoutes(trails: Trail[]): TripRoute[] {
  const catalog: TripRoute[] = trails.map(t => ({ key: `trail:${t.id}`, trailId: t.id, name: t.trail_name, location: t.park ? `${t.park.park_name}, ${t.park.state}` : "Trail catalog", distance: t.length_miles, elevation: t.elevation_ft, difficulty: t.difficulty, days: "1", image: t.image_url ?? undefined, source: "catalog" }));
  const names = new Set(catalog.map(t => t.name.toLowerCase()));
  return [...catalog, ...PACK_TRAILS.filter(t => !names.has(t.name.toLowerCase())).map(t => ({ key: `guide:${t.name}`, name: t.name, location: t.location, distance: t.distance, elevation: t.elevation, days: t.days, difficulty: t.difficulty, source: "guide" as const }))];
}
export function planLink(route: TripRoute) { return `/trips?${new URLSearchParams({ trail: route.key })}`; }
export function recordingLink(trip: Trip) {
  const params = new URLSearchParams({ type: "hike" });
  if (trip.route?.trailId) params.set("trail_id", trip.route.trailId);
  return `/record/live?${params}`;
}
export function isTrip(value: unknown): value is Trip {
  if (!value || typeof value !== "object") return false;
  const t = value as Trip;
  return typeof t.id === "string" && typeof t.name === "string" && typeof t.date === "string" && typeof t.days === "number" && Number.isFinite(t.days) && typeof t.notes === "string" && Array.isArray(t.items) && t.items.every(isTripItem) && (t.route === null || (typeof t.route === "object" && typeof t.route.name === "string" && typeof t.route.key === "string"));
}
export function isGearItem(value: unknown): value is GearItem {
  if (!value || typeof value !== "object") return false;
  const g = value as GearItem;
  return typeof g.id === "string" && typeof g.name === "string" && typeof g.category === "string" && ["Base", "Worn", "Consumable"].includes(g.type) && Number.isFinite(g.qty) && g.qty > 0 && Number.isFinite(g.weight) && g.weight >= 0 && Number.isFinite(g.price) && typeof g.link === "string";
}
function isTripItem(value: unknown): value is TripItem { return isGearItem(value) && typeof (value as TripItem).packed === "boolean"; }
export function tripDate(date: string) { return date ? new Date(`${date}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "Dates to decide"; }
